["SAK","ZAN",[[34.3,135],[33.625,134.875],[1.625,104.375],[1.375,104.375],[1.125,104.125],[1.625,102.625],[5.625,96.875],[5.625,95.375],[-6.17,39.2]]]
]$fix$::jsonb) e;

do $$
declare
  c_a constant uuid := '00000000-0403-4000-8000-0000000000a1';
  c_j constant uuid := '00000000-0403-4000-8000-0000000000b1';
  v_pl    uuid;
  v_fl    uuid;
  v_port  uuid;
  v_ocode text;
  v_title int;
  v_wave  numeric;
  v_r     jsonb;
  v_co    text;
  v_rows  int;
  v_bad   text;
  v_shut  int;
  v_line  int;
  v_n     int;
begin
  if coalesce(obj_description('public.sea_leg_asks'::regclass, 'pg_class'), '') not like '%0403%' then
    raise exception 'PROOF 98 FAIL: 0403 is not in this world';
  end if;
  update public.world_config set value = 'false'::jsonb where key = 'economy_closed';
  update public.world_config set value = 'true'::jsonb where key = 'sea_conditions_bite';

  foreach v_co in array array['FAR_FLEET', 'FAR_POWER'] loop
    if v_co = 'FAR_FLEET' then
      v_pl := public.new_house(c_a, 'Casa do Rumo 98', 'PRT', 'LIS', 'Rumo', 'barca', 'Rumo', null, false);
      update public.fleets set port_id = (select id from public.ports where code = 'ACA') where player_id = v_pl;
      perform cmd.assume_identity(c_a);
    else
      perform cmd.assume_identity(c_j);
      v_r := cmd.found_house('Casa do Rumo Longe 98', 'JPN');
      v_pl := (v_r ->> 'player_id')::uuid;
    end if;
    select f.id, f.port_id, p.code into v_fl, v_port, v_ocode from public.fleets f join public.ports p on p.id = f.port_id where f.player_id = v_pl;
    v_title := public.title_level(v_pl);
    v_wave := public.fleet_wave(v_fl);
    if v_title <> 1 or v_ocode is distinct from (select x.c from (values ('FAR_FLEET', 'ACA'), ('FAR_POWER', 'SAK')) x(k, c) where x.k = v_co)
       or (select count(*) from c98 c where c.a = v_ocode) <> (select count(*) - 1 from public.ports p where p.kind = 'HARBOUR') then
      raise exception 'PROOF 98 FAIL: % is not a title-1 company lying at the harbour this proof holds every course from (she lies at %, title %)', v_co, v_ocode, v_title;
    end if;
    select count(*), count(*) filter (where g.gate is not null), count(*) filter (where g.gate is distinct from g.line),
           string_agg(g.b, ' ') filter (where nullif(t.sea -> 'refusal', 'null'::jsonb) is distinct from g.gate)
      into v_rows, v_shut, v_line, v_bad
      from (select row_number() over (order by c.b) as i, c.b, public.sea_gate(v_pl, v_fl, b.port_id, c.course) as gate,
                   public.sea_gate(v_pl, v_fl, b.port_id, jsonb_build_array(jsonb_build_array(a.roadstead_lat, a.roadstead_lon), jsonb_build_array(b.roadstead_lat, b.roadstead_lon))) as line
              from c98 c join public.sea_reaches b on b.code = c.b join public.sea_reaches a on a.code = c.a where c.a = v_ocode) g
      join jsonb_array_elements(public.sea_routes(v_fl, v_title, v_wave,
             (select jsonb_agg(jsonb_build_array(v_ocode, c.b) order by c.b) from c98 c where c.a = v_ocode))) with ordinality t(sea, i) on t.i = g.i;
    if v_rows < 200 or v_bad is not null or v_shut < 1 or v_shut = v_rows or v_line < 1 then
      raise exception 'PROOF 98 FAIL: % lit, at %: of % harbours these wear a Trade tag that is not the door''s answer on the plotted course: %; % shut, % where the straight line answers otherwise',
        v_co, v_ocode, v_rows, left(coalesce(v_bad, 'none'), 600), v_shut, v_line;
    end if;
    raise notice 'PASS: DOOR_% — lit, at %: all % harbours wear the door''s own answer on the course she would really sail (% shut, % open); for % of them the door answers otherwise on the straight line',
      v_co, v_ocode, v_rows, v_shut, v_rows - v_shut, v_line;
    perform cmd.assume_identity(null);
  end loop;

  select count(*), string_agg(a.code || '-' || b.code, ' ') filter (where not s.zones @> public.course_zones(n.course)) into v_n, v_bad
    from public.npc_courses n join public.ports a on a.id = n.from_port join public.ports b on b.id = n.to_port
    join public.sea_leg_asks s on s.from_port = n.from_port and s.to_port = n.to_port;
  if v_n < 100 or v_bad is not null then
    raise exception 'PROOF 98 FAIL: of % remembered courses these cross a sea their pair row does not hold: %', v_n, left(v_bad, 600);
  end if;
  raise notice 'PASS: ROW_HOLDS_COURSE — all % remembered courses cross only seas their pair''s row holds', v_n;
end $$;
